// ============ CONFIG ============
const TZ_OFFSET       = '+04:00';            // Asia/Dubai
const DAILY_SLOTS     = ['10:00', '13:00'];  // 2 per day
const SKIP_WEEKDAYS   = [0];                 // 0 = Sunday
const BUFFER_PLAN_CAP = 10;
const LEAD_MINUTES    = 15;
const LOOKAHEAD_DAYS  = 30;
const SKIP_STATUSES   = ['skip', 'archived'];
// ================================

const norm   = (v) => String(v ?? '').trim();
const lower  = (v) => norm(v).toLowerCase();
const isDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(v);
const slotMs = (d, t) => new Date(`${d}T${t}:00${TZ_OFFSET}`).getTime();

const nowMs = Date.now() + LEAD_MINUTES * 60000;

const cleanTime = (v) => {
  const m = norm(v).match(/^(\d{1,2}):(\d{2})/);
  return m ? `${m[1].padStart(2, '0')}:${m[2]}` : '';
};


// ============================================================
// 1. BUILD OCCUPIED SLOT LIST
// ============================================================
// Every slot already spoken for, so we never double-book.
const occupied = new Set();


// ---- From the previous node / sheet ----
for (const item of $input.all()) {
  const r = item.json;

  const d = norm(r.Scheduled_Date).slice(0, 10);
  const t = cleanTime(r.Scheduled_Time);

  if (isDate(d) && t) {
    occupied.add(`${d}T${t}`);
  }
}


// ---- From Buffer's live queue ----
// Buffer is also treated as a source of truth because its schedule
// may not perfectly match the sheet.
try {
  const edges =
    $('Check Buffer Headroom')
      .first()
      .json
      ?.data
      ?.posts
      ?.edges ?? [];

  for (const e of edges) {
    const due = e?.node?.dueAt;

    if (!due) continue;

    // Convert UTC Buffer date into Dubai local time.
    const local = new Date(
      new Date(due).getTime() + 4 * 3600 * 1000
    );

    const date = local.toISOString().slice(0, 10);
    const time = local.toISOString().slice(11, 16);

    occupied.add(`${date}T${time}`);
  }
} catch (e) {
  // Don't fail the workflow just because Buffer data
  // isn't available.
}


// ============================================================
// 2. BUILD FORWARD-LOOKING FREE SLOT GRID
// ============================================================
const grid = [];

const today = new Date(
  Date.now() + 4 * 3600 * 1000
); // Dubai local

for (let i = 0; i < LOOKAHEAD_DAYS; i++) {

  const day = new Date(
    Date.UTC(
      today.getUTCFullYear(),
      today.getUTCMonth(),
      today.getUTCDate() + i
    )
  );

  // Skip configured weekdays.
  if (SKIP_WEEKDAYS.includes(day.getUTCDay())) {
    continue;
  }

  const dateStr = day.toISOString().slice(0, 10);

  for (const t of DAILY_SLOTS) {

    const ms = slotMs(dateStr, t);

    // Don't schedule anything in the past or too close to now.
    if (ms <= nowMs) {
      continue;
    }

    // Don't double-book.
    if (occupied.has(`${dateStr}T${t}`)) {
      continue;
    }

    grid.push({
      date: dateStr,
      time: t,
      ms,
    });
  }
}


// Sort available slots chronologically.
grid.sort((a, b) => a.ms - b.ms);

let gridPos = 0;

const takeNextSlot = () => {
  return gridPos < grid.length
    ? grid[gridPos++]
    : null;
};


// ============================================================
// 3. DETERMINE WHICH POSTS ARE ELIGIBLE
// ============================================================
const dated   = [];
const undated = [];
const skipped = [];


// ------------------------------------------------------------
// DUPLICATE-ROW GUARD
// ------------------------------------------------------------
// The sheet write-back matches on Post_ID and updates the FIRST
// matching row. So if the same Post_ID exists twice, sending the
// second copy stamps the Buffer ID onto the FIRST row and leaves
// the copy blank. A blank Buffer_post_id reads as "never sent",
// so that copy gets re-posted on every single run, forever.
//
// This is exactly what produced 13 duplicate posts in Buffer
// from 9 duplicated rows (rows 39-47 repeating rows 29-37).
// ------------------------------------------------------------
const fingerprint = (t) =>
  norm(t).replace(/\s+/g, ' ').slice(0, 120).toLowerCase();

const sentIds   = new Set();   // Post_IDs that already carry a Buffer ID
const sentTexts = new Set();   // and their text, to catch copies under a new ID

for (const item of $input.all()) {
  const r = item.json;
  if (!norm(r.Buffer_post_id)) continue;
  sentIds.add(norm(r.Post_ID));
  sentTexts.add(fingerprint(r.Post_Text));
}

const seenIds   = new Set();   // guards against two copies inside one run
const seenTexts = new Set();

for (const item of $input.all()) {

  // Entire original JSON object from the previous node.
  const r = item.json;

  const postId = norm(r.Post_ID);
  const text   = norm(r.Post_Text);

  const skip = (why) => {
    skipped.push(
      `${postId || '(no id)'}: ${why}`
    );
  };


  // ----------------------------------------------------------
  // Required values
  // ----------------------------------------------------------
  if (!postId || !text) {
    continue;
  }


  // ----------------------------------------------------------
  // Must be approved
  // ----------------------------------------------------------
  if (lower(r.Approved) !== 'approved') {
    skip('not approved');
    continue;
  }


  // ----------------------------------------------------------
  // Don't send posts already created in Buffer
  // ----------------------------------------------------------
  if (norm(r.Buffer_post_id)) {
    continue;
  }


  // ----------------------------------------------------------
  // Duplicate guard - see notes at the top of section 3
  // ----------------------------------------------------------
  const fp = fingerprint(text);

  // A copy of a row that has already been sent
  if (sentIds.has(postId)) {
    skip('DUPLICATE ROW - this Post_ID already has a Buffer ID on another row');
    continue;
  }

  if (sentTexts.has(fp)) {
    skip('DUPLICATE TEXT - this exact content has already been sent');
    continue;
  }

  // Two copies of the same post inside this one run
  if (seenIds.has(postId)) {
    skip('DUPLICATE ROW - Post_ID appears more than once in the sheet');
    continue;
  }

  if (seenTexts.has(fp)) {
    skip('DUPLICATE TEXT - identical content appears more than once in the sheet');
    continue;
  }

  seenIds.add(postId);
  seenTexts.add(fp);


  // ----------------------------------------------------------
  // Don't process skipped / archived records
  // ----------------------------------------------------------
  if (SKIP_STATUSES.includes(lower(r.Status))) {
    skip(`status ${lower(r.Status)}`);
    continue;
  }


  // ----------------------------------------------------------
  // Normalize useful post properties
  // ----------------------------------------------------------
  const hashtags = norm(r.Hashtags);
  const imageUrl = norm(r.Image_URL);


  // ==========================================================
  // IMPORTANT:
  // Preserve ALL JSON fields from the previous node.
  //
  // ...r means fields such as:
  //
  // row_number
  // Post_ID
  // Week_Of
  // Story_Topic
  // Vertical
  // Post_Variant
  // Platform
  // Post_Text
  // Hashtags
  // Scheduled_Date
  // Scheduled_Time
  // Status
  // Source_Link
  // Image_URL
  // Character_Count
  // Approved
  // Notes
  // Buffer_scheduled_at
  // Buffer_post_id
  //
  // plus ANY future columns you add upstream.
  // ==========================================================
  const base = {

    // Preserve all original JSON
    ...r,

    // Add normalized / workflow-friendly fields
    postId,

    fullText: hashtags
      ? `${text}\n\n${hashtags}`
      : text,

    imageUrl,

    hasImage: /^https?:\/\//i.test(imageUrl),

    topic: norm(r.Story_Topic),

    notes: norm(r.Notes),
  };


  // ----------------------------------------------------------
  // Check existing scheduled date/time
  // ----------------------------------------------------------
  const d = norm(r.Scheduled_Date).slice(0, 10);
  const t = cleanTime(r.Scheduled_Time);


  // ==========================================================
  // ALREADY HAS A VALID DATE + TIME
  // ==========================================================
  if (isDate(d) && t) {

    // Don't send stale scheduled posts.
    if (slotMs(d, t) <= nowMs) {
      skip(
        `${d} ${t} already passed - clear the date to let it be rescheduled`
      );
      continue;
    }


    dated.push({
      ...base,

      dateStr: d,
      timeStr: t,

      // False means this was already scheduled upstream.
      assigned: false,
    });

  } else {

    // No valid schedule, so we'll assign one.
    undated.push(base);
  }
}


// ============================================================
// 4. ASSIGN FREE SLOTS TO UNDATED POSTS
// ============================================================
for (const p of undated) {

  const g = takeNextSlot();

  if (!g) {
    skipped.push(
      `${p.postId}: no free slot in the next ${LOOKAHEAD_DAYS} days`
    );
    continue;
  }


  dated.push({
    ...p,

    dateStr: g.date,
    timeStr: g.time,

    // True means this Code node assigned the slot.
    assigned: true,
  });
}


// ============================================================
// 5. ADD FINAL BUFFER SCHEDULING FIELDS
// ============================================================
dated.forEach((p) => {

  p.dueAt =
    `${p.dateStr}T${p.timeStr}:00${TZ_OFFSET}`;

  p.when =
    `${p.dateStr} ${p.timeStr}`;

  p.sortMs =
    slotMs(p.dateStr, p.timeStr);
});


// Process oldest / soonest first.
dated.sort((a, b) => a.sortMs - b.sortMs);


// ============================================================
// 6. DETERMINE CURRENT BUFFER HEADROOM
// ============================================================
let inBuffer = null;

try {

  const edges =
    $('Check Buffer Headroom')
      .first()
      .json
      ?.data
      ?.posts
      ?.edges;

  if (Array.isArray(edges)) {
    inBuffer = edges.length;
  }

} catch (e) {
  // Leave inBuffer as null.
}


// If Buffer couldn't be checked, default to sending only 2.
// Otherwise respect configured Buffer ceiling.
const headroom =
  inBuffer === null
    ? 2
    : Math.max(
        0,
        BUFFER_PLAN_CAP - inBuffer
      );


// Only send as many posts as Buffer currently has room for.
const send = dated.slice(0, headroom);


// Everything else waits.
dated
  .slice(headroom)
  .forEach((p) => {

    skipped.push(
      `${p.postId}: waiting - Buffer full (${inBuffer}/${BUFFER_PLAN_CAP})`
    );

  });


// ============================================================
// 7. DEBUG LOGGING
// ============================================================
console.log(
  `Buffer ${inBuffer ?? '?'}/${BUFFER_PLAN_CAP}. ` +
  `Ready ${dated.length}, sending ${send.length}.`
);

console.log(
  'SENDING:\n  ' +
  (
    send
      .map(
        (p) =>
          `${p.when}  ${p.postId}` +
          `${p.assigned ? '  (slot assigned)' : ''}`
      )
      .join('\n  ')
    ||
    'nothing'
  )
);

if (skipped.length) {

  console.log(
    'SKIPPED:\n  ' +
    skipped.join('\n  ')
  );

}


// ============================================================
// 8. OUTPUT
// ============================================================
//
// Each output item now contains:
//
// 1. ALL original JSON fields from the previous node
// 2. Normalized convenience fields
// 3. Assigned scheduling fields
//
// Example access downstream:
//
// {{$json.Post_ID}}
// {{$json.Post_Text}}
// {{$json.Source_Link}}
// {{$json.Image_URL}}
// {{$json.Vertical}}
// {{$json.Post_Variant}}
//
// PLUS:
//
// {{$json.postId}}
// {{$json.fullText}}
// {{$json.imageUrl}}
// {{$json.hasImage}}
// {{$json.dateStr}}
// {{$json.timeStr}}
// {{$json.dueAt}}
// {{$json.when}}
// {{$json.assigned}}
//

return send.map((json) => ({
  json
}));

const src = $('One At A Time').first().json ?? {};
const res = $input.first().json ?? {};

const bufferPostId = res.id ?? res?.post?.id ?? res?.data?.createPost?.post?.id ?? '';
const ok = Boolean(bufferPostId);

let err = '';
if (!ok) {
  err = res?.error?.message ?? res?.error ?? res?.message ?? res?.data?.createPost?.message
    ?? (Array.isArray(res?.errors) ? res.errors.map(e => e.message).join('; ') : '')
    ?? 'Buffer returned no post ID';
}

const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');

return [{ json: {
  Post_ID: src.postId,
  // Written back so the sheet shows when it actually goes out
  Scheduled_Date: src.dateStr,
  Scheduled_Time: src.timeStr,
  Status: ok ? 'Scheduled' : 'Failed',
  Buffer_post_id: bufferPostId,
  Buffer_scheduled_at: ok ? (res.dueAt ?? res?.post?.dueAt ?? src.dueAt ?? '') : '',
  Notes: ok ? src.notes : [src.notes, `[${stamp}] ${err}`].filter(Boolean).join(' ').slice(0, 480),
  _ok: ok,
  _when: src.when,
  _topic: src.topic,
  _img: src.hasImage ? 'image' : 'text',
  _assigned: !!src.assigned,
} }];

// The loop's done output carries every row that passed through the sheet write,
// one per iteration. Success = a Buffer ID came back.
const rows = $input.all().map(i => i.json ?? {});

const ok     = rows.filter(r => String(r.Buffer_post_id ?? '').trim());
const failed = rows.filter(r => !String(r.Buffer_post_id ?? '').trim());

const lines = [`Sent ${ok.length} of ${rows.length} to Buffer.`];

if (ok.length) {
  lines.push('');
  ok.forEach(r => lines.push(`  ${r.Scheduled_Date} ${r.Scheduled_Time}  ${r.Post_ID}`));
}
if (failed.length) {
  lines.push('', 'FAILED');
  failed.forEach(r => lines.push(`  ${r.Post_ID}  ${r.Notes ?? ''}`));
}
if (!rows.length) lines.push('Nothing sent. See the Pick Posts To Send console for why.');

const summary = lines.join('\n');
console.log(summary);
return [{ json: { sent: ok.length, failed: failed.length, summary } }];
